draw:
var mu0 = 4 * Math.PI * 1e-7;
var I = p.current, a = p.radius / 1000, rp = p.probe / 1000;
var Bsurf = mu0 * I / (2 * Math.PI * a);
var B = rp <= a ? mu0 * I * rp / (2 * Math.PI * a * a) : mu0 * I / (2 * Math.PI * rp);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

// ---- left panel: cross-section ----
var cx = W * 0.24, cy = H * 0.52;
var rmax = a * 3;                       // metres shown across the panel
var pix = Math.min(W * 0.20, H * 0.38) / rmax;   // pixels per metre
var wireR = a * pix;

ctx.strokeStyle = C.rule;
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(cx, cy, wireR, 0, Math.PI * 2); ctx.fill(); ctx.stroke();

// current-out-of-page dots
ctx.fillStyle = C.figure;
for (var ix = -2; ix <= 2; ix++) {
  for (var iy = -2; iy <= 2; iy++) {
    var dx = ix * wireR * 0.42, dy = iy * wireR * 0.42;
    if (dx * dx + dy * dy < wireR * wireR * 0.75) {
      ctx.beginPath(); ctx.arc(cx + dx, cy + dy, 1.6, 0, Math.PI * 2); ctx.fill();
    }
  }
}

// the Amperian circle
var pr = rp * pix;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.arc(cx, cy, pr, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// a marker running round the loop, faster where B is bigger
var speed = 0.7 + 5.0 * (B / (Bsurf + 1e-30));
var ang = (t * speed) % (Math.PI * 2);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx + pr * Math.cos(ang), cy + pr * Math.sin(ang), 4, 0, Math.PI * 2); ctx.fill();

// B arrow, tangent to the loop at the marker
var tx = -Math.sin(ang), ty = Math.cos(ang);
var hx = cx + pr * Math.cos(ang), hy = cy + pr * Math.sin(ang);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(hx, hy); ctx.lineTo(hx + tx * 18, hy + ty * 18); ctx.stroke();
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.fillText("current I out of page", cx - wireR, cy + Math.min(W * 0.20, H * 0.38) + 16);
ctx.fillStyle = C.accent;
ctx.fillText("Amperian loop", cx - wireR, cy - Math.min(W * 0.20, H * 0.38) - 6);

// ---- right panel: B against r ----
var gx0 = W * 0.50, gx1 = W - 14, gy0 = 18, gy1 = H - 30;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1); ctx.stroke();

var Bpeak = Bsurf * 1.15;
var GX = function (r) { return gx0 + (r / rmax) * (gx1 - gx0); };
var GY = function (b) { return gy1 - (b / Bpeak) * (gy1 - gy0); };

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 160; k++) {
  var r = rmax * k / 160;
  var bv = r <= a ? mu0 * I * r / (2 * Math.PI * a * a) : mu0 * I / (2 * Math.PI * r);
  if (r === 0) { ctx.moveTo(GX(0), GY(0)); } else { ctx.lineTo(GX(r), GY(bv)); }
}
ctx.stroke();
ctx.lineWidth = 1;

// surface line
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(GX(a), gy0); ctx.lineTo(GX(a), gy1); ctx.stroke();
ctx.setLineDash([]);

// probe marker on the curve
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(GX(rp), GY(B), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("B", gx0 + 4, gy0 + 10);
ctx.fillText("r", gx1 - 10, gy1 + 14);
ctx.fillStyle = C.faint;
ctx.fillText("surface", GX(a) + 3, gy0 + 24);
ctx.fillStyle = C.ink;
ctx.fillText("rises as r inside, falls as 1/r outside", gx0, H - 8);

out.note = "r = " + p.probe.toFixed(1) + " mm, B = " + (B * 1e6).toFixed(1) +
  " microtesla  (surface value " + (Bsurf * 1e6).toFixed(1) + ")";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

var x0 = W * 0.10, x1 = W * 0.90;
var yTop = H * 0.30, yBot = H * 0.62;

// solenoid walls: rows of turns, current out of page on top, into page on bottom
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, yTop); ctx.lineTo(x1, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yBot); ctx.lineTo(x1, yBot); ctx.stroke();

var n = 14;
for (var i = 0; i < n; i++) {
  var x = x0 + (x1 - x0) * (i + 0.5) / n;
  // top: dot (out of page)
  ctx.strokeStyle = C.figure; ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(x, yTop, 4.5, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(x, yTop, 1.6, 0, Math.PI * 2); ctx.fill();
  // bottom: cross (into page)
  ctx.beginPath(); ctx.arc(x, yBot, 4.5, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x - 3.2, yBot - 3.2); ctx.lineTo(x + 3.2, yBot + 3.2);
  ctx.moveTo(x + 3.2, yBot - 3.2); ctx.lineTo(x - 3.2, yBot + 3.2);
  ctx.stroke();
}

// interior field arrows
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
for (var j = 0; j < 5; j++) {
  var ax = x0 + (x1 - x0) * (0.12 + 0.19 * j);
  var ay = (yTop + yBot) / 2;
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax + 34, ay); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ax + 34, ay); ctx.lineTo(ax + 27, ay - 4);
  ctx.lineTo(ax + 27, ay + 4); ctx.closePath();
  ctx.fillStyle = C.accent; ctx.fill();
}
ctx.lineWidth = 1;

// the Amperian rectangle
var rx0 = W * 0.32, rx1 = W * 0.62;
var ryIn = (yTop + yBot) / 2 + 14;
var ryOut = H * 0.13;
ctx.strokeStyle = C.ink;
ctx.setLineDash([5, 4]);
ctx.strokeRect(rx0, ryOut, rx1 - rx0, ryIn - ryOut);
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("1  inside, along B: gives B L", rx0 + 6, ryIn - 6);
ctx.fillText("3  outside: B is about zero", rx0 + 6, ryOut - 6);
ctx.save();
ctx.translate(rx0 - 6, (ryIn + ryOut) / 2);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("2, 4  perpendicular to B: zero", 0, 0);
ctx.restore();
ctx.textAlign = "left";

ctx.fillStyle = C.figure;
ctx.fillText("turns carrying I, n per metre", x0, yBot + 26);
ctx.fillStyle = C.accent;
ctx.fillText("B = mu0 n I, uniform inside", x0, H - 10);
ctx.fillStyle = C.ink;
ctx.fillText("loop encloses n L turns", rx1 + 8, ryOut + 14);

var mu0 = 4 * Math.PI * 1e-7;
var Iin = p.inner, Ish = p.shield, rp = p.probe / 1000;
var a = 0.001, b = 0.003, c = 0.005;   // metres: inner radius, shield inner, shield outer

function enc(r) {
  var e = 0;
  e += r >= a ? Iin : Iin * (r * r) / (a * a);
  if (r > b) {
    var f = r >= c ? 1 : (r * r - b * b) / (c * c - b * b);
    e -= Ish * f;
  }
  return e;
}
function field(r) { return r <= 0 ? 0 : mu0 * enc(r) / (2 * Math.PI * r); }

var B = field(rp);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

// ---- left: cross-section ----
var cx = W * 0.22, cy = H * 0.50;
var rmax = 0.008;
var pix = Math.min(W * 0.18, H * 0.40) / rmax;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, cy, c * pix, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, b * pix, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, a * pix, 0, Math.PI * 2); ctx.fill();

// shield hatching
ctx.strokeStyle = C.faint;
for (var k = 0; k < 24; k++) {
  var th = k * Math.PI * 2 / 24;
  ctx.beginPath();
  ctx.moveTo(cx + b * pix * Math.cos(th), cy + b * pix * Math.sin(th));
  ctx.lineTo(cx + c * pix * Math.cos(th), cy + c * pix * Math.sin(th));
  ctx.stroke();
}

// Amperian circle with a travelling marker
var pr = rp * pix;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.arc(cx, cy, pr, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
var dir = B >= 0 ? 1 : -1;
var ang = dir * (t * 1.6) % (Math.PI * 2);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx + pr * Math.cos(ang), cy + pr * Math.sin(ang), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("core  shield  gap", cx - c * pix, cy + Math.min(W * 0.18, H * 0.40) + 18);

// ---- right: B(r) ----
var gx0 = W * 0.46, gx1 = W - 14, gy0 = 18, gy1 = H - 30;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(gx0, gy0); ctx.lineTo(gx0, gy1); ctx.lineTo(gx1, gy1); ctx.stroke();

var peak = 0;
for (var k2 = 1; k2 <= 200; k2++) {
  var rr = rmax * k2 / 200;
  var v = Math.abs(field(rr));
  if (v > peak) peak = v;
}
if (peak <= 0) peak = 1e-9;
peak = peak * 1.15;

var GX = function (r) { return gx0 + (r / rmax) * (gx1 - gx0); };
var GY = function (bv) { return gy1 - (bv / peak) * (gy1 - gy0); };

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var k3 = 1; k3 <= 200; k3++) {
  var r3 = rmax * k3 / 200;
  var b3 = Math.abs(field(r3));
  if (k3 === 1) { ctx.moveTo(GX(r3), GY(b3)); } else { ctx.lineTo(GX(r3), GY(b3)); }
}
ctx.stroke();
ctx.lineWidth = 1;

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(GX(b), gy0); ctx.lineTo(GX(b), gy1); ctx.stroke();
ctx.beginPath(); ctx.moveTo(GX(c), gy0); ctx.lineTo(GX(c), gy1); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(GX(rp), GY(Math.abs(B)), 4, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("B", gx0 + 4, gy0 + 10);
ctx.fillText("r", gx1 - 10, gy1 + 14);
ctx.fillStyle = C.faint;
ctx.fillText("3 mm", GX(b) + 3, gy0 + 24);
ctx.fillText("5 mm", GX(c) + 3, gy0 + 38);
ctx.fillStyle = C.ink;
ctx.fillText("outside, only the net current matters", gx0, H - 8);

out.note = "r = " + p.probe.toFixed(2) + " mm: enclosed " + enc(rp).toFixed(2) +
  " A, B = " + (Math.abs(B) * 1e6).toFixed(1) + " microtesla";
